node.doctext:
This is great! Thank you so much for your replies! They were very helpful. Okay, so a little clarification:

<code>

sub ccc{65}
print "\n" . ccc.ccc.ccc.ccc;  # this evaluates to numbers
print "\n" . 65.65.65.65.65;   # this evaluates to letters
# Ok. It's a little weird, but it is what it is.

my $A = sub { print "\nWELCOME! :-) (@_)\n"; 1 };
my $B = sub { print "\nGO AWAY! >:( (@_)\n"; 2 };
my $X = time % 2 ? $A : $B;
print $X->(77);
$A = 0;
$B = 0;
$X = 0;

# So, if I create anonymous subs,
# I can later simply "erase" them?
# This is great.
#
# But now, what happens to my anonymous subroutines?
# Do they simply disappear or stay in memory somewhere?

print "\n" . __PACKAGE__;
print "\n" . __FILE__;
print "\n" . __LINE__;
print "\n\n";
#sub MY{ my $K = __SUB__; }  # Why is this giving me an error?
#MY;

sub P{(6,7,8)}       # returns an array
print "\n".(P)[0];
print "\n".(P)[1];
print "\n".(P)[2];
# Makes sense.

</code>
